import{_ as i,l as s,o as a,c as p,v as t,p as n,x as o,d as c,i as d,S as l}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"管道与 IPC","description":"","frontmatter":{"title":"管道与 IPC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipc-pipe.md","filePath":"cs/ipc-pipe.md","lastUpdated":1789023840000}'),h={name:"cs/ipc-pipe.md"};function m(_,e,E,B,f,u){const r=s("Mermaid");return a(),p("div",null,[e[1]||(e[1]=t('<h1 id="管道与-ipc" tabindex="-1">管道与 IPC <a class="header-anchor" href="#管道与-ipc" aria-label="Permalink to &quot;管道与 IPC&quot;">​</a></h1><div class="epigraph"><p>管道是两个进程之间的字节流：一端写，一端读，内核做缓冲。</p><footer>—— 据 Ritchie and Thompson, The UNIX Time-Sharing System, 1974；Stevens, UNIX Network Programming 整理</footer></div><p><a href="/cs/sigmask">上一课</a>只能投递编号事件。<a href="/cs/process-image">进程映像</a>各有各的地址空间，用户指针不能直接递给别人。缺口是：两个进程要传<strong>字节</strong>，必须经过内核对象。本课以管道为原型，把共享内存与消息队列留作同一层的变体，不写成百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>父进程 fork 后想把标准输出接到子进程输入。若只靠信号，连一个字符都传不了。若把数据写进文件再读，延迟与命名都重。管道给出匿名字节流：内核环形缓冲，写满则写者阻塞，读空则读者阻塞，会合点正是<a href="/cs/syscall-path">系统调用</a>里的睡眠与<a href="/cs/interrupt-bottom-half">下半部</a>式的唤醒——这里唤醒者是另一端的 <code>read</code>/<code>write</code>，不是设备。</p><p>本课不把套接字当管道的特例讲完；套接字在网络课才出现，但会复用「文件描述符上的字节流」。</p><p><span class="marginnote">匿名管道只在亲缘进程间继承描述符。命名管道（FIFO）把同一对象挂进目录，让无亲缘进程也能打开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>pipe</code> 分配内核缓冲与两个描述符。写拷贝入核，读拷贝出核。关闭写端后读者收到文件结束；关闭读端后写者得信号 <code>SIGPIPE</code>。共享内存反过来：映射同一物理页，字节不经拷贝，但必须另做同步——同步是后面几课。消息队列按消息边界投递，仍是内核缓冲。</p>',9)),(a(),n(l,null,{default:o(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E8%BF%9B%E7%A8%8B%20write%22%5D%20--%3E%20BUF%5B%22%E5%86%85%E6%A0%B8%E7%AE%A1%E9%81%93%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20R%5B%22%E8%AF%BB%E8%BF%9B%E7%A8%8B%20read%22%5D%0A%20%20BUF%20--%3E%20BLK%5B%22%E6%BB%A1%E5%88%99%E5%86%99%E7%9D%A1%20%2F%20%E7%A9%BA%E5%88%99%E8%AF%BB%E7%9D%A1%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IPC 把进程映像的隔离留住：页表仍分开，只有内核或双方同意的共享页能看见同一字节。管道强制流式、单向（标准匿名管道）；双向要两根或套接字。阻塞把调度指标重新请进来：写者睡时 CPU 可以给别人，这是管道与忙等轮询的差别。</p><p>信号可以宣布「管道断了」，但仍不是负载。本课之后，默认「进程间有字节通道」；通道上的竞态要另说。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Mach port 的全部权利，不把 D-Bus 当内核原语。也不讲网络字节序：那是还没有对端主机。Unix 域套接字与管道相近，细节不背。</p><p>容量上限是内核参数。写端一次 <code>write</code> 在管道上不一定原子，只有小写在 POSIX 下有保证。</p><p>本课不把 <code>SOCK_SEQPACKET</code> 当管道的第三种。</p><p>后课默认：亲缘进程可用管道传字节。多执行流同时碰同一缓冲或同一共享页时会发生什么，下一课叫竞争与临界区。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管道是内核缓冲的字节流；满写睡、空读睡。</li><li>共享内存更省拷贝，但把互斥推给后课。</li><li>套接字是更后的跨机器通道，接口仍像文件。</li><li>出处：Ritchie and Thompson, <em>CACM</em> 1974；Stevens, <em>UNP</em>；Tanenbaum <em>MOS</em>。</li></ul>',10))])}const T=i(h,[["render",m]]);export{A as __pageData,T as default};
